// Support sees the SHAPE of the failure, never the payload.
public record WorkflowProbe(
        String  workflowId,
        String  failedStep,
        String  errorCode,
        Instant occurredAt,
        int     payloadFieldCount,   // "11 fields present"
        boolean patientLinked        // yes/no, never who
) {
    // Built by hand from the entity. Adding a PHI field to Claim does not
    // change this record, so it cannot leak through this endpoint.
    static WorkflowProbe from(Claim c) {
        return new WorkflowProbe(
            c.getWorkflowId(), c.getFailedStep(), c.getErrorCode(),
            c.getOccurredAt(), c.getPayload().size(), c.getPatient() != null);
    }
}

public String callForTenant(String tenantId, Prompt p) {
    // Envelope: KMS holds the master key, we store only the wrapped DEK.
    byte[] wrapped = vault.wrappedKeyFor(tenantId);
    char[] apiKey  = kms.decrypt(wrapped);        // plaintext, in memory only
    try {
        return openAi.withKey(apiKey).complete(p);
    } catch (AuthException e) {
        // Never let the key reach a log line or a stack trace.
        throw new TenantKeyInvalid(tenantId);
    } finally {
        Arrays.fill(apiKey, '\0');                // scrub before GC
    }
}

